```{.r .cell-code}
data_renamed |>
  distinct(Common_Name) |>
  arrange(Common_Name) |>
  gt() |>
  tab_header(
    title = "Fish species present in the original dataset"
  ) |>
  tab_style(
    style = list(
      cell_fill(color = "#C19A6B"),
      cell_text(
        color = "white",
        weight = "bold"
      )
    ),
    locations = cells_body(
      rows = Common_Name == "Brown Trout"
    )
  )
```

