### Let's add some statistics.


::: {.cell}

```{.r .cell-code}
# Prepare data
brown_trout_month <- brown_trout |>
  mutate(
    month = month(
      Date,
      label = TRUE,
      abbr = FALSE
    )
  ) |>
  filter(
    !is.na(month),
    !is.na(Weight_g)
  )

# Run one-way ANOVA
weight_anova <- aov(
  Weight_g ~ month,
  data = brown_trout_month
)

# Run Tukey post hoc test
weight_tukey <- TukeyHSD(weight_anova)

# Create comparison table
weight_tukey$month |>
  as.data.frame() |>
  rownames_to_column("Comparison") |>
  rename(
    `Mean Difference (g)` = diff,
    `Lower 95% CI` = lwr,
    `Upper 95% CI` = upr,
    `Adjusted p-value` = `p adj`
  ) |>
  mutate(
    Significance = case_when(
      `Adjusted p-value` < 0.001 ~ "***",
      `Adjusted p-value` < 0.01  ~ "**",
      `Adjusted p-value` < 0.05  ~ "*",
      TRUE                       ~ "ns"
    )
  ) |>
  arrange(`Adjusted p-value`) |>
  gt() |>
  fmt_number(
    columns = c(
      `Mean Difference (g)`,
      `Lower 95% CI`,
      `Upper 95% CI`
    ),
    decimals = 1
  ) |>
  fmt_number(
    columns = `Adjusted p-value`,
    decimals = 4
  ) |>
  tab_header(
    title = "Tukey Post Hoc Comparisons of Brown Trout Weight by Month",
    subtitle = "Pairwise comparisons following one-way ANOVA"
  ) |>
  cols_align(
    align = "center",
    columns = everything()
  ) |>
  tab_style(
    style = list(
      cell_fill(color = "#4E79A7"),
      cell_text(
        color = "white",
        weight = "bold"
      )
    ),
    locations = cells_column_labels(
      columns = everything()
    )
  ) |>
  tab_style(
    style = list(
      cell_fill(color = "#C19A6B"),
      cell_text(
        color = "white",
        weight = "bold"
      )
    ),
    locations = cells_body(
      rows = `Adjusted p-value` < 0.05
    )
  )
```

