### Within which water temperature range do brown trout exhibit the highest weight?

Water temperature explains only about 36% of the differences in fish weight. So temperature is related to weight, but the relationship is weak. p \< 0.001. The relationship is statistically significant. This means the pattern is unlikely to be due to random chance in this dataset.


::: {.cell}

```{.r .cell-code}
library(tidyverse)
library(cowplot)

# Prepare data
weight_temperature <- ctrout |>
  filter(
    !is.na(Temperature_C),
    !is.na(Weight_g)
  )

# Fit linear regression model
weight_temp_model <- lm(
  Weight_g ~ Temperature_C,
  data = weight_temperature
)

# Extract model statistics
model_summary <- summary(weight_temp_model)

r_squared <- model_summary$r.squared
p_value <- coef(model_summary)[
  "Temperature_C",
  "Pr(>|t|)"
]

# Create label for the plot
stats_label <- paste0(
  "R² = ",
  round(r_squared, 3),
  "\n",
  ifelse(
    p_value < 0.001,
    "p < 0.001",
    paste0(
      "p = ",
      round(p_value, 3)
    )
  )
)

# Create the plot
weight_temp_plot <- weight_temperature |>
  ggplot(
    aes(
      x = Temperature_C,
      y = Weight_g
    )
  ) +
  geom_point(
    color = "steelblue",
    alpha = 0.6,
    size = 3
  ) +
  geom_smooth(
    method = "lm",
    se = TRUE,
    color = "black"
  ) +
  geom_point(
    data = Tristan,
    aes(
      x = Temperature_C,
      y = Weight_g
    ),
    inherit.aes = FALSE,
    color = "lightsalmon4",
    shape = 18,
    size = 5
  ) +
  geom_text(
    data = Tristan,
    aes(
      x = Temperature_C,
      y = Weight_g,
      label = "Tristan",
      hjust = 1.3,
      vjust = 1
    ),
    inherit.aes = FALSE,
    color = "lightsalmon4",
    nudge_y = 120
  ) +
  annotate(
    "text",
    x = Inf,
    y = Inf,
    label = stats_label,
    hjust = 3,
    vjust = 2,
    fontface = "bold",
    size = 4
  ) +
  labs(
    title = "Brown Trout Weight and Water Temperature",
    subtitle = "Linear regression between water temperature and fish weight",
    x = "Water temperature (°C)",
    y = "Weight (g)"
  ) +
  theme_cowplot()

# Display the plot
weight_temp_plot
